package app.fitness.core

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.int
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive

/**
 * The FIT enum names the PC app's `fitparse` knows (generated by `tools/export_fit_enums.py`).
 * Used instead of the Garmin SDK's own names so the stored strings match the PC's exactly.
 */
object FitEnums {
    private val root: JsonObject by lazy {
        val text = FitEnums::class.java.getResourceAsStream("/fit/fitparse_enums.json")!!.bufferedReader().readText()
        Json.parseToJsonElement(text).jsonObject
    }

    private fun table(name: String): Map<Int, String> =
        root.getValue(name).jsonObject.entries.associate { (k, v) -> k.toInt() to v.jsonPrimitive.content }

    val sport: Map<Int, String> by lazy { table("sport") }
    val manufacturer: Map<Int, String> by lazy { table("manufacturer") }
    val garminProduct: Map<Int, String> by lazy { table("garmin_product") }
    val garminProductManufacturers: Set<Int> by lazy {
        root.getValue("garmin_product_manufacturers").jsonArray.map { it.jsonPrimitive.int }.toSet()
    }
}
